html:
{#- Variants of a Sales Proposal: for each linked quotation that has a variant title, its title, two paragraphs, and a table of
    its products (the rows of Variant Products that belong to the quotation) with their picture.
    Letterhead and footer are added here, like in the "Sales Proposal" format. -#}
{% set variants = doc.quotations | selectattr("variant_title") | list %}
<div {% if print_settings.repeat_header_footer %}id="header-html" class="hidden-pdf"{% endif %}>
    {% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
</div>
{% if print_settings.repeat_header_footer %}
<div id="footer-html" class="visible-pdf">
    {% if not no_letterhead and footer %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}
    <p class="text-center small page-number visible-pdf">
        {{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}
    </p>
</div>
{% endif %}

{% for variant in variants %}
{% set items = doc.variant_items | selectattr("quotation", "equalto", variant.quotation) | list %}
<div class="bn-variant{% if not loop.first %} bn-variant-next{% endif %}">
    <h1>
        {%- if variants|length > 1 -%}
            {{ _("Variant {0}: {1}").format(loop.index, (variant.variant_title | e)) }}
        {%- else -%}
            {{ variant.variant_title | e }}
        {%- endif -%}
    </h1>
    {% if variant.variant_intro %}<p class="bn-text">{{ variant.variant_intro | e }}</p>{% endif %}
    {% if variant.variant_benefits %}<p class="bn-text">{{ variant.variant_benefits | e }}</p>{% endif %}

    {% if items %}
    <table class="bn-variant-items">
        {% for item in items %}
        <tr>
            <td class="bn-variant-image">{% if item.image %}<img src="{{ item.image }}">{% endif %}</td>
            <td class="bn-variant-text">
                <div class="bn-variant-name">{{ (item.item_name or item.item_code) | e }}</div>
                <div class="bn-text bn-variant-description">{{ (item.description or "") | e }}</div>
            </td>
        </tr>
        {% endfor %}
    </table>
    {% endif %}
</div>
{% endfor %}
<style>
    .bn-variant { padding: 16mm 16mm 0 16mm; font-size: 10pt; line-height: 1.6; }
    .bn-variant-next { page-break-before: always; }
    .bn-variant h1 { font-size: 17pt; line-height: 1.25; margin: 0 0 8mm 0; color: #0a1a2b; border-left: 3pt solid #f28f25; padding-left: 4mm; }
    .bn-variant p { margin: 0 0 5mm 0; }
    .bn-text { white-space: pre-line; }  /* the texts are plain text: keep their line breaks */
    .bn-variant-items { width: 100%; border-collapse: collapse; margin-top: 8mm; }
    .bn-variant-items tr { page-break-inside: avoid; }
    .bn-variant-items td { vertical-align: top; padding: 4mm 0; border-top: 0.5pt solid #d5dde5; }
    .bn-variant-image { width: 36mm; padding-right: 6mm !important; }
    .bn-variant-image img { max-width: 34mm; max-height: 30mm; }
    .bn-variant-name { font-weight: 600; margin-bottom: 1mm; }
    .bn-variant-description { margin-bottom: 2mm; }
</style>
